package com.fitbite.service;
import com.fitbite.dto.AuthDtos.*; import com.fitbite.entity.*; import com.fitbite.repository.*; import com.fitbite.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AuthService { private final UserRepository users; private final RoleRepository roles; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository users,RoleRepository roles,PasswordEncoder encoder,JwtService jwt){this.users=users;this.roles=roles;this.encoder=encoder;this.jwt=jwt;}
 public AuthResponse register(RegisterRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new IllegalArgumentException("Email is already registered"); RoleEntity role=roles.findByName(Role.USER).orElseThrow(); User u=User.builder().name(r.name()).email(r.email().toLowerCase()).password(encoder.encode(r.password())).roles(new HashSet<>(Set.of(role))).build();users.save(u);return response(u);}
 public AuthResponse login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("Invalid email or password");return response(u);}
 private AuthResponse response(User u){Set<String> rs=u.getRoles().stream().map(x->x.getName().name()).collect(java.util.stream.Collectors.toSet());return new AuthResponse(jwt.generate(u.getId(),u.getEmail(),rs),u.getId(),u.getName(),u.getEmail(),rs);}
}
